bool GlyphuxKernels::IsOutput(int32 Binding)
{
	switch (Binding)
	{
	case 7: return true;
	case 8: return true;
	case 10: return true;
	default: return false;
	}
}

const TCHAR* GlyphuxKernels::BindingName(int32 Binding)
{
	switch (Binding)
	{
	case 0: return TEXT("Glyphux.Glyphs");
	case 1: return TEXT("Glyphux.Work");
	case 2: return TEXT("Glyphux.Edges");
	case 3: return TEXT("Glyphux.Contours");
	case 4: return TEXT("Glyphux.Curves");
	case 5: return TEXT("Glyphux.Tiles");
	case 6: return TEXT("Glyphux.Candidates");
	case 7: return TEXT("Glyphux.Field");
	case 8: return TEXT("Glyphux.Stencil");
	case 9: return TEXT("Glyphux.Corners");
	case 10: return TEXT("Glyphux.Atlas");
	default: return TEXT("Glyphux.Unknown");
	}
}

